path = "/home/jhan/workspace/titan/cache-perf/asimov/gen_perf_cme.py"
s = open(path).read()
def rep(start, end, new):
    global s
    assert s.count(start) == 1, ("start", start[:60], s.count(start)); assert s.count(end) == 1, ("end", end[:60], s.count(end))
    i, j = s.index(start), s.index(end); assert i < j; s = s[:i] + new + s[j:]
def sub(old, new, n=1):
    global s
    assert s.count(old) == n, ("sub", old[:70], s.count(old)); s = s.replace(old, new)

